export const changeStudents = (id, postToUpdate) => {
  const options = {
    method: "PATCH",
    body: JSON.stringify(postToUpdate),
    headers: {
      "Content-Type": "application/json; charset=UTF-8",
    },
  };

  return fetch(`http://localhost:3000/students/${id}`, options).then((res) =>
    res.json(),
  );
};
